    assert "c_playerPropSuppliesLimit" in AI_SOURCE and "MC_Resources" in AI_SOURCE
    # v0.1.12: skin catalog and parent-centered add-on geometry regression checks.
    for uid in ["Reactor","TechLab","BarracksReactor","FactoryReactor","StarportReactor","BarracksTechLab","FactoryTechLab","StarportTechLab"]:
        node = parsed["UnitData"].find(f"./CUnit[@id='{uid}']")
